content:
:root {
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-light: #eff6ff;
  --color-primary-border: #bfdbfe;
  --color-danger: #ef4444;
  --color-danger-hover: #dc2626;
  --color-danger-light: #fef2f2;
  --color-success: #10b981;
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-surface-muted: #f1f5f9;
  --color-text-main: #1e293b;
  --color-text-muted: #64748b;
  --color-text-placeholder: #94a3b8;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;
  --color-border-focus: #93c5fd;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Hiragino Sans",
    "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリ全体のコンテナ */
.app-container {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

@media (min-width: 640px) {
  .app-container {
    padding: 48px 20px;
  }
}

/* メインカード */
.todo-card {
  width: 100%;
  max-width: 580px;
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--color-border);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

@media (min-width: 640px) {
  .todo-card {
    padding: 32px 28px;
  }
}

/* ヘッダーエリア */
.todo-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.todo-title {
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

.todo-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-muted);
}

/* 進捗バーコンテナ */
.todo-progress-container {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background-color: var(--color-surface-muted);
  padding: 12px 16px;
  border-radius: var(--radius-md);
}

.todo-progress-bar {
  width: 100%;
  height: 8px;
  background-color: var(--color-border);
  border-radius: 9999px;
  overflow: hidden;
}

.todo-progress-fill {
  height: 100%;
  background-color: var(--color-success);
  border-radius: inherit;
  transition: width var(--transition-normal);
}

.todo-progress-text {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-muted);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* 入力フォーム */
.input-form {
  display: flex;
  gap: 8px;
}

.todo-input {
  flex: 1;
  padding: 12px 16px;
  font-size: 0.9375rem;
  color: var(--color-text-main);
  background-color: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.todo-input::placeholder {
  color: var(--color-text-placeholder);
}

.todo-input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.add-button {
  padding: 12px 20px;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-surface);
  background-color: var(--color-primary);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  white-space: nowrap;
  transition: background-color var(--transition-fast), transform 0.1s ease, box-shadow var(--transition-fast);
  min-height: 44px;
}

.add-button:hover {
  background-color: var(--color-primary-hover);
}

.add-button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.35);
}

.add-button:active {
  transform: scale(0.98);
}

.add-button:disabled {
  background-color: var(--color-text-placeholder);
  cursor: not-allowed;
  transform: none;
}

/* フィルターボタン群 */
.filter-container {
  display: flex;
  gap: 6px;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 12px;
}

.filter-button {
  flex: 1;
  padding: 8px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  background-color: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-height: 38px;
}

.filter-button:hover {
  background-color: var(--color-surface-muted);
  color: var(--color-text-main);
}

.filter-button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
}

.filter-button-active {
  background-color: var(--color-primary-light);
  color: var(--color-primary);
  font-weight: 600;
  border-color: var(--color-primary-border);
}

/* TODOリスト */
.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 120px;
}

/* 個別タスクアイテム */
.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  transition: border-color var(--transition-fast), background-color var(--transition-fast), box-shadow var(--transition-fast);
}

.todo-item:hover {
  border-color: var(--color-border-hover);
  box-shadow: var(--shadow-md);
}

.todo-item-completed {
  background-color: var(--color-bg);
  border-color: var(--color-border);
}

/* チェックボックスとテキスト */
.todo-checkbox-label {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  cursor: pointer;
  user-select: none;
  min-width: 0;
}

.todo-checkbox {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid var(--color-border-hover);
  border-radius: 6px;
  outline: none;
  cursor: pointer;
  position: relative;
  transition: all var(--transition-fast);
  flex-shrink: 0;
}

.todo-checkbox:checked {
  background-color: var(--color-success);
  border-color: var(--color-success);
}

.todo-checkbox:checked::after {
  content: "";
  position: absolute;
  left: 6px;
  top: 2px;
  width: 5px;
  height: 10px;
  border: solid var(--color-surface);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

.todo-checkbox:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.25);
}

.todo-text {
  font-size: 0.9375rem;
  color: var(--color-text-main);
  word-break: break-word;
  transition: color var(--transition-fast), text-decoration var(--transition-fast);
}

.todo-item-completed .todo-text {
  color: var(--color-text-placeholder);
  text-decoration: line-through;
}

/* 削除ボタン */
.delete-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  color: var(--color-text-placeholder);
  background-color: transparent;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  margin-left: 8px;
  flex-shrink: 0;
  transition: color var(--transition-fast), background-color var(--transition-fast), box-shadow var(--transition-fast);
}

.delete-button:hover {
  color: var(--color-danger);
  background-color: var(--color-danger-light);
}

.delete-button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.25);
  background-color: var(--color-danger-light);
  color: var(--color-danger);
}

.delete-button:active {
  transform: scale(0.94);
}

/* 空ステート */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 36px 16px;
  color: var(--color-text-muted);
  font-size: 0.9375rem;
  text-align: center;
  background-color: var(--color-bg);
  border: 1px dashed var(--color-border);
  border-radius: var(--radius-md);
}

/* 統計サマリー */
.stats-summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  border-top: 1px solid var(--color-border);
  padding-top: 14px;
}

export interface TodoTask {
  id: string;
  text: string;
  completed: boolean;
  createdAt: string;
}

export type FilterType = 'all' | 'active' | 'completed';

export interface FilterOption {
  key: FilterType;
  label: string;
}

export interface TodoInputProps {
  onAdd: (text: string) => void;
}

export interface TodoItemProps {
  task: TodoTask;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

export interface TodoStats {
  total: number;
  completed: number;
  active: number;
  progressPercentage: number;
}

import { useState, useRef, type FormEvent, type ChangeEvent } from 'react';
import { TodoInputProps } from '../types';

const TodoInput = ({ onAdd }: TodoInputProps) => {
  const [inputText, setInputText] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const trimmed = inputText.trim();
    if (!trimmed) return;
    onAdd(trimmed);
    setInputText('');
    inputRef.current?.focus();
  };

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
  };

  return (
    <form className="input-form" onSubmit={handleSubmit}>
      <input
        ref={inputRef}
        type="text"
        className="todo-input"
        placeholder="新しいタスクを入力してください..."
        value={inputText}
        onChange={handleChange}
        maxLength={100}
        aria-label="新しいタスク名"
      />
      <button
        type="submit"
        className="add-button"
        disabled={!inputText.trim()}
      >
        追加
      </button>
    </form>
  );
};

export default TodoInput;

import { TodoItemProps } from '../types';

const TodoItem = ({ task, onToggle, onDelete }: TodoItemProps) => {
  const { id, text, completed } = task;

  const itemClassName = completed
    ? 'todo-item todo-item-completed'
    : 'todo-item';

  const handleDelete = () => {
    if (window.confirm(`「${text}」を削除してもよろしいですか？`)) {
      onDelete(id);
    }
  };

  return (
    <li className={itemClassName}>
      <label className="todo-checkbox-label">
        <input
          type="checkbox"
          className="todo-checkbox"
          checked={completed}
          onChange={() => onToggle(id)}
        />
        <span className="todo-text">{text}</span>
      </label>
      <button
        type="button"
        className="delete-button"
        onClick={handleDelete}
        aria-label={`${text}を削除`}
        title="タスクを削除"
      >
        <svg
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <polyline points="3 6 5 6 21 6" />
          <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
          <line x1="10" y1="11" x2="10" y2="17" />
          <line x1="14" y1="11" x2="14" y2="17" />
        </svg>
      </button>
    </li>
  );
};

export default TodoItem;

import { useState, useEffect, useMemo } from 'react';
import { TodoTask, FilterType } from './types';
import TodoInput from './components/TodoInput';
import TodoItem from './components/TodoItem';
import './index.css';

const STORAGE_KEY = 'todo_app_tasks';

const INITIAL_TASKS: TodoTask[] = [
  {
    id: 'task-1',
    text: '牛乳と卵を買う',
    completed: true,
    createdAt: '2025-01-01T09:00:00.000Z',
  },
  {
    id: 'task-2',
    text: '週報メールを作成して提出する',
    completed: false,
    createdAt: '2025-01-01T10:30:00.000Z',
  },
  {
    id: 'task-3',
    text: '部屋の掃除とゴミ出し',
    completed: false,
    createdAt: '2025-01-01T11:00:00.000Z',
  },
  {
    id: 'task-4',
    text: '読書（30分）',
    completed: false,
    createdAt: '2025-01-01T14:15:00.000Z',
  },
];

const App = () => {
  const [tasks, setTasks] = useState<TodoTask[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved) as TodoTask[];
      }
    } catch {
      // localStorageのパースエラーまたはアクセス制限時のフォールバック
    }
    return INITIAL_TASKS;
  });

  const [filter, setFilter] = useState<FilterType>('all');

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch {
      // localStorageの保存失敗時のフォールバック
    }
  }, [tasks]);

  const handleAddTask = (text: string) => {
    const newTask: TodoTask = {
      id: crypto.randomUUID(),
      text,
      completed: false,
      createdAt: new Date().toISOString(),
    };
    setTasks((prev) => [newTask, ...prev]);
  };

  const handleToggleTask = (id: string) => {
    setTasks((prev) =>
      prev.map((task) =>
        task.id === id ? { ...task, completed: !task.completed } : task
      )
    );
  };

  const handleDeleteTask = (id: string) => {
    setTasks((prev) => prev.filter((task) => task.id !== id));
  };

  const handleClearCompleted = () => {
    if (window.confirm('完了済みのタスクをすべて削除してもよろしいですか？')) {
      setTasks((prev) => prev.filter((task) => !task.completed));
    }
  };

  const filteredTasks = useMemo(() => {
    switch (filter) {
      case 'active':
        return tasks.filter((task) => !task.completed);
      case 'completed':
        return tasks.filter((task) => task.completed);
      case 'all':
      default:
        return tasks;
    }
  }, [tasks, filter]);

  const totalCount = tasks.length;
  const completedCount = tasks.filter((task) => task.completed).length;
  const activeCount = totalCount - completedCount;
  const progressPercentage =
    totalCount === 0 ? 0 : Math.round((completedCount / totalCount) * 100);

  return (
    <div className="app-container">
      <div className="todo-card">
        <header className="todo-header">
          <h1 className="todo-title">やることリスト</h1>
          <p className="todo-subtitle">今日のタスクを整理して、効率よく進めましょう</p>
        </header>

        <section className="todo-progress-container" aria-label="タスク達成度">
          <div className="todo-progress-text">
            <span>達成度: {progressPercentage}%</span>
            <span>
              完了 {completedCount} / 合計 {totalCount} 件
            </span>
          </div>
          <div className="todo-progress-bar">
            <div
              className="todo-progress-fill"
              style={{ width: `${progressPercentage}%` }}
            />
          </div>
        </section>

        <TodoInput onAdd={handleAddTask} />

        <nav className="filter-container" aria-label="フィルター切り替え">
          <button
            type="button"
            className={
              filter === 'all'
                ? 'filter-button filter-button-active'
                : 'filter-button'
            }
            onClick={() => setFilter('all')}
          >
            すべて ({totalCount})
          </button>
          <button
            type="button"
            className={
              filter === 'active'
                ? 'filter-button filter-button-active'
                : 'filter-button'
            }
            onClick={() => setFilter('active')}
          >
            未完了 ({activeCount})
          </button>
          <button
            type="button"
            className={
              filter === 'completed'
                ? 'filter-button filter-button-active'
                : 'filter-button'
            }
            onClick={() => setFilter('completed')}
          >
            完了済み ({completedCount})
          </button>
        </nav>

        {filteredTasks.length === 0 ? (
          <div className="empty-state">
            {filter === 'completed'
              ? '完了したタスクはまだありません。'
              : filter === 'active'
              ? 'すべてのタスクが完了しています！お疲れ様でした。'
              : 'タスクがありません。上のフォームから追加してください。'}
          </div>
        ) : (
          <ul className="todo-list">
            {filteredTasks.map((task) => (
              <TodoItem
                key={task.id}
                task={task}
                onToggle={handleToggleTask}
                onDelete={handleDeleteTask}
              />
            ))}
          </ul>
        )}

        <footer className="stats-summary">
          <span>残りタスク: {activeCount} 件</span>
          {completedCount > 0 && (
            <button
              type="button"
              className="filter-button"
              style={{ flex: 'none' }}
              onClick={handleClearCompleted}
            >
              完了済みを削除
            </button>
          )}
          <span>完了済み: {completedCount} 件</span>
        </footer>
      </div>
    </div>
  );
};

export default App;
